  const keys = Object.keys(extracted);
  if (keys.length === 0) return null;

  return {
    headerName: EXTRACTED_GROUP_HEADER,
    children: keys.map((key) => ({
      headerName: key,
      headerGroupComponent: EllipsisHeaderGroup,
