const nestExecutionGroup = (group: ColGroupDef, runs: CompareRun[]): ColGroupDef => {
  const leaves = getChildren(group);

  return {
    headerName: EXECUTION_GROUP_HEADER,
    children: EXECUTION_FIELD_GROUPS.map(({ fieldLabel, colId }) =>
